import assert from 'node:assert/strict';
import test from 'node:test';
import {readFileSync} from 'node:fs';
import {numberInputProblem,numberInputValid,nativeNumberSettings,type NumberPolicy,type NumberRules} from '../app/ui/number';

// Captured before replacing Scale's implementation. Expected data is never regenerated by this test.
const baseline=JSON.parse(readFileSync(new URL('./fixtures/numeric-pilot-241-baseline.json',import.meta.url),'utf8')) as {
 baselineCommit:string;defaultProblem:string;
 cases:Array<{value:string;policy:NumberPolicy;rules:NumberRules;problem:string;valid:boolean}>;
 settings:Array<{props:Parameters<typeof nativeNumberSettings>[0];result:ReturnType<typeof nativeNumberSettings>}>;
};
test('numeric facade preserves the frozen Scale validation baseline',()=>{
 assert.equal(baseline.baselineCommit,'11affc1c');assert.equal(baseline.cases.length,1584);
 for(const [index,vector]of baseline.cases.entries()){
  assert.equal(numberInputProblem(vector.value,vector.policy,vector.rules),vector.problem,`problem vector ${index}: ${JSON.stringify(vector)}`);
  assert.equal(numberInputValid(vector.value,vector.policy,vector.rules),vector.valid,`valid vector ${index}: ${JSON.stringify(vector)}`);
 }
 assert.equal(numberInputProblem('0','decimal'),baseline.defaultProblem,'rules default remains optional');
 for(const vector of baseline.settings)assert.deepEqual(nativeNumberSettings(vector.props),vector.result,JSON.stringify(vector.props));
});

test('Scale facades and public package entries expose exactly the same renderer and validator objects',()=>{
 const localInput=require('../app/ui/input') as typeof import('../app/ui/input');
 const localNumber=require('../app/ui/number') as typeof import('../app/ui/number');
 const numeric=require('owncoding-ui/numeric') as typeof import('owncoding-ui/numeric');
 const pure=require('owncoding-ui/number-utils') as typeof import('owncoding-ui/number-utils');
 const root=require('owncoding-ui') as Record<string,unknown>;
 for(const name of ['InputBase','TextareaBase'] as const){assert.ok(numeric[name]);assert.equal(localInput[name],numeric[name]);assert.equal(root[name],numeric[name]);}
 for(const name of ['NumericControl','NumberInput','PercentageInput'] as const){assert.ok(numeric[name]);assert.equal(localNumber[name],numeric[name]);assert.equal(root[name],numeric[name]);}
 for(const name of ['numberInputProblem','numberInputValid','nativeNumberSettings'] as const){assert.equal(typeof pure[name],'function');assert.equal(localNumber[name],pure[name]);assert.equal(numeric[name],pure[name]);assert.equal(root[name],pure[name]);}
});
